// windowFixed(3): batch trades into groups of 3
// [T1, T2, T3, T4, T5, T6, T7] → [[T1,T2,T3], [T4,T5,T6], [T7]]
List<List<Trade>> batches = trades.stream()
    .gather(Gatherers.windowFixed(3))  // intermediate: Stream<Trade> → Stream<List<Trade>>
    .toList();

// windowSliding(3): sliding window of size 3
// [T1, T2, T3, T4, T5] → [[T1,T2,T3], [T2,T3,T4], [T3,T4,T5]]
List<List<Trade>> windows = trades.stream()
    .gather(Gatherers.windowSliding(3))
    .toList();

// fold: running balance (intermediate accumulator)
// [100, -50, 200, -30] → [100, 50, 250, 220]
List<Integer> runningBalance = Stream.of(100, -50, 200, -30)
    .gather(Gatherers.fold(() -> 0, Integer::sum))  // NOT a terminal — intermediate!
    .toList();

