package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.stream.Gatherers;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.assertThat;

class GatherersTest {

    @Test
    void windowFixedBatchesTransactions() {
        // windowFixed(2) groups the stream into fixed-size batches of 2
        List<List<Integer>> batches = Stream.of(10, 20, 30, 40, 50)
            .gather(Gatherers.windowFixed(2))
            .toList();

        assertThat(batches).containsExactly(
            List.of(10, 20), List.of(30, 40), List.of(50));
    }
}
